/* Stock helper text that is faded with alpha (Settings help at 70 %, the conversation "Online" line at
   50 %) measures 3.0-3.5:1 on the real pixels. Solid muted ink instead (no hook for these yet). */
:is([class*="text-[var(--muted-foreground)]/70"], [class*="text-[var(--muted-foreground)]/60"], [class*="text-[var(--foreground)]/50"]):not(input, textarea) {
  color: var(--lm-muted);
}
